var i=`0538-fahsa`;var o=`world-0538`;var t=`YE`;var a=`western-asia`;var s=4;var r=141;var l={en:`Fahsa`,ua:`Фахса`};var g={en:`A traditional dish from Yemen, centered on lamb, yellow onion, tomato, garlic. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ємен. Основні складники: ягнятина, жовта цибуля, помідор, часник. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 13 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 13 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:13,i:[[`lamb`,760,`g`],[`yellow-onion`,200,`g`],[`sunflower-oil`,55,`ml`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 115 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 115 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:115,i:[[`water`,900,`ml`],[`tomato`,350,`g`],[`garlic`,5,`clove`],[`ground-cumin`,6,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`ground-fenugreek`,7,`g`],[`cilantro`,55,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[]}];var m={slug:i,id:o,country:`YE`,region:a,servings:4,minutes:141,title:l,text:g,steps:d};export{t as country,m as default,o as id,r as minutes,a as region,s as servings,i as slug,d as steps,g as text,l as title};